SELECT tblCase.CaseID, [case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty] AS CaseNo, Disposition.Disposition, Disposition.[PI Settlement Amount], Disposition.Dispo_Date, Disposition.Dispo_Atty, Disposition.DispoJudge, Disposition.DispoOppC, [Matter and AR].Date2, [Matter and AR].Pay_Outlay, [Matter and AR].Charge, [Matter and AR].Payment, [Trust Account].TDate, [Trust Account].TMatter, [Trust Account].Debit, [Trust Account].Credit, tblCase.Matter_type, tblCase.CaseOpenDate, tblCase.Court, tblCase.Retainer
FROM (((tblCase INNER JOIN Billing ON tblCase.CaseID = Billing.CaseID) INNER JOIN Disposition ON tblCase.CaseID = Disposition.CaseID) INNER JOIN [Matter and AR] ON tblCase.CaseID = [Matter and AR].CaseID) INNER JOIN [Trust Account] ON tblCase.CaseID = [Trust Account].CaseID;